package app.lensdrop.transfer;
import android.content.*;import android.database.Cursor;import org.json.*;import java.nio.file.*;import java.util.*;
import static app.lensdrop.transfer.WatchLedgerIntegrationTest.*;
public final class RecoveryReliabilityTest {
 static int count;static void check(String name,Check test)throws Exception{try(Fixture f=new Fixture()){test.run(f);count++;System.out.println("PASS "+name);}}
 static void fail(Checked c)throws Exception{try{c.run();}catch(IllegalStateException e){return;}throw new AssertionError("Expected guarded rejection");}
 interface Checked{void run()throws Exception;}
 static String staged(Fixture f)throws Exception {Path p=f.dir.resolve("immutable.jpg");Files.write(p,new byte[]{1,2,3,4});return p.toString();}
 static void assign(Fixture f,String j)throws Exception{f.pool("group");f.w.nextGroup(S);f.w.select(S,j);}
 public static void main(String[] args)throws Exception{
  check("Blocked assigned upload may be retired, retaining its guest and original IDs",f->{f.baseline(0);String j=f.incoming("content://image/a",false);assign(f,j);String g=f.delivery(j);f.q.state(j,"blocked","source_changed",1,0);yes(f.q.hasOtherPending("eventB"));RecoveryLedger.retireUpload(f.q,S,j);eq(f.q.jobState(S,j),"retired_local");eq(f.delivery(j),g);yes(!f.q.hasOtherPending("eventB"));eq(f.count("SELECT count(*) FROM recovery_audit"),1L);});
  check("Retirement does not delete source/staged file and survives restart",f->{f.baseline(0);String j=f.incoming("content://image/a",false),path=staged(f);ContentValues v=new ContentValues();v.put("spool",path);v.put("sha","a".repeat(64));v.put("upload","remote-upload-id");f.q.update(j,v);RecoveryLedger.retireUpload(f.q,S,j);f.restart();yes(Files.exists(Path.of(path)));eq(f.q.jobState(S,j),"retired_local");eq(f.count("SELECT count(*) FROM jobs WHERE upload='remote-upload-id' AND sha='"+"a".repeat(64)+"'"),1L);});
  check("Late worker state writes cannot resurrect retired upload",f->{f.baseline(0);String j=f.incoming("content://image/a",false);RecoveryLedger.retireUpload(f.q,S,j);f.q.state(j,"uploaded",null,1,0);f.q.retryBlocked(S);f.q.recover();eq(f.q.jobState(S,j),"retired_local");});
  check("In-flight upload retirement rejected until checkpoint",f->{f.baseline(0);String j=f.incoming("content://image/a",false);f.q.state(j,"uploading",null,0,0);fail(()->RecoveryLedger.retireUpload(f.q,S,j));eq(f.count("SELECT count(*) FROM recovery_audit"),0L);});
  check("Wrong scope cannot retire a job",f->{f.baseline(0);String j=f.incoming("content://image/a",false);fail(()->RecoveryLedger.retireUpload(f.q,"other",j));eq(f.q.jobState(S,j),"candidate");});
  check("Retirement idempotence never invents extra audit actions",f->{f.baseline(0);String j=f.incoming("content://image/a",false);RecoveryLedger.retireUpload(f.q,S,j);fail(()->RecoveryLedger.retireUpload(f.q,S,j));eq(f.count("SELECT count(*) FROM recovery_audit"),1L);});
  check("Completed upload not relabeled as retired",f->{f.baseline(0);String j=f.incoming("content://image/a",false);f.q.state(j,"uploaded",null,0,0);fail(()->RecoveryLedger.retireUpload(f.q,S,j));eq(f.q.jobState(S,j),"uploaded");});
  check("Changed file requires deliberate retirement before candidate creation",f->{f.baseline(0);String j=f.incoming("content://image/a",false);assign(f,j);f.q.state(j,"blocked","source_changed",1,0);fail(()->RecoveryLedger.replacement(f.q,S,j,"NEW.JPG",120,20,"b".repeat(64),staged(f),UUID.randomUUID().toString()));eq(f.count("SELECT count(*) FROM jobs"),1L);});
  check("Replacement permits same URI/size/mtime but new content revision without guest inheritance",f->{f.baseline(0);String j=f.incoming("content://image/a",false);assign(f,j);String g=f.delivery(j);RecoveryLedger.retireUpload(f.q,S,j);String n=UUID.randomUUID().toString();RecoveryLedger.replacement(f.q,S,j,"NEW.JPG",120,20,"b".repeat(64),staged(f),n);eq(f.q.jobState(S,n),"candidate");eq(f.delivery(n),null);eq(f.delivery(j),g);eq(f.count("SELECT source_revision FROM jobs WHERE id='"+n+"'"),1L);eq(f.count("SELECT count(*) FROM recovery_audit"),2L);});
  check("Unselected changed candidate never enters upload queue",f->{f.baseline(0);String j=f.incoming("content://image/a",false);RecoveryLedger.retireUpload(f.q,S,j);String n=UUID.randomUUID().toString();RecoveryLedger.replacement(f.q,S,j,"NEW.JPG",120,20,"b".repeat(64),staged(f),n);eq(f.q.due(S),null);eq(f.w.candidates(S,0).getJSONObject(0).getString("spool"),staged(f));});
  check("Replacement source notifications cannot duplicate or move its destination",f->{f.baseline(0);String j=f.incoming("content://image/a",false);RecoveryLedger.retireUpload(f.q,S,j);String n=UUID.randomUUID().toString();RecoveryLedger.replacement(f.q,S,j,"NEW.JPG",120,20,"b".repeat(64),staged(f),n);f.incoming("content://image/a",false);eq(f.count("SELECT count(*) FROM jobs"),2L);assign(f,n);String g=f.delivery(n);f.w.arrival(S,"content://image/a","NEW.JPG",999,123,false,false);eq(f.delivery(n),g);});
  check("Identical content is not relabeled as a new replacement",f->{f.baseline(0);String j=f.incoming("content://image/a",false);ContentValues v=new ContentValues();v.put("sha","a".repeat(64));f.q.update(j,v);RecoveryLedger.retireUpload(f.q,S,j);fail(()->RecoveryLedger.replacement(f.q,S,j,"NEW.JPG",120,20,"a".repeat(64),staged(f),UUID.randomUUID().toString()));eq(f.count("SELECT count(*) FROM jobs"),1L);});
  check("Repeated replacement with same bytes rejected even from an older record",f->{f.baseline(0);String j=f.incoming("content://image/a",false);RecoveryLedger.retireUpload(f.q,S,j);RecoveryLedger.replacement(f.q,S,j,"NEW.JPG",120,20,"b".repeat(64),staged(f),UUID.randomUUID().toString());fail(()->RecoveryLedger.replacement(f.q,S,j,"NEW.JPG",120,20,"b".repeat(64),staged(f),UUID.randomUUID().toString()));eq(f.count("SELECT count(*) FROM jobs"),2L);});
  check("Late single-photo replacement does not mutate issued single QR",f->{f.baseline(0);f.pool("single");f.w.mode(S,"single");String j=f.incoming("content://image/a",false),g=f.w.select(S,j),link=f.w.group(S,g).getString("guest_path");f.q.state(j,"uploaded",null,1,0);String n=UUID.randomUUID().toString();RecoveryLedger.replacement(f.q,S,j,"NEW.JPG",120,20,"b".repeat(64),staged(f),n);eq(f.w.group(S,g).getString("guest_path"),link);eq(f.delivery(n),null);eq(f.delivery(j),g);});
  check("Retired uploads are counted separately from uploaded/candidate/skipped",f->{f.baseline(0);String j=f.incoming("content://image/a",false);RecoveryLedger.retireUpload(f.q,S,j);JSONObject s=f.q.snapshot(S).getJSONObject("production");eq(s.getLong("retired"),1L);eq(s.getLong("uploaded"),0L);eq(s.getLong("queued"),0L);});
  check("Healthy queued file stays due while bad file has local backoff",f->{f.baseline(0);String a=f.incoming("content://image/a",false),b=f.incoming("content://image/b",false);assign(f,a);f.w.select(S,b);f.q.state(a,"retry","jpeg_incomplete",1,System.currentTimeMillis()+60000);eq(f.q.due(S).id,b);});
  check("Five exhausted file retries block only that file",f->{f.baseline(0);String a=f.incoming("content://image/a",false),b=f.incoming("content://image/b",false);assign(f,a);f.w.select(S,b);ContentValues v=new ContentValues();v.put("file_failures",5);v.put("state","blocked");f.q.update(a,v);eq(f.q.due(S).id,b);f.q.retryBlocked(S);try(Cursor c=f.q.getReadableDatabase().rawQuery("SELECT file_failures FROM jobs WHERE id=?",new String[]{a})){c.moveToFirst();eq(c.getInt(0),0);}});
  check("Showing old QR remains unchanged when candidate is assigned to current receiver",f->{f.baseline(0);f.pool("group");String a=f.w.nextGroup(S),b=f.w.nextGroup(S);f.w.show(S,a);String j=f.incoming("content://image/new",false);f.w.select(S,j);eq(f.delivery(j),b);eq(f.w.shown(S),a);eq(f.w.active(S),b);});
  check("Quick Undo deadline does not redirect receiver; explicit Resume remains",f->{f.baseline(0);f.pool("group");String a=f.w.nextGroup(S),b=f.w.nextGroup(S);f.q.getWritableDatabase().execSQL("UPDATE watch_sessions SET undo_until=1 WHERE scope=?",new Object[]{S});fail(()->f.w.undo(S));eq(f.w.active(S),b);f.w.resume(S,a);eq(f.w.active(S),a);});
  check("Retired print preserves remote uncertainty and blocks late local reactivation",f->{try(PrintQueue p=new PrintQueue(new Context(f.dir.toString()))){String id=UUID.randomUUID().toString();p.add(S,new JSONObject().put("id",id),staged(f),"hybrid");p.update(id,"blocked","outcome_unknown","network",0,false);yes(p.hasPending());RecoveryLedger.retirePrint(p,S,id);yes(!p.hasPending());p.update(id,"queued","ready","",0,true);JSONObject r=p.history(S,0).getJSONObject(0);eq(r.getString("state"),"retired_local");eq(r.getString("remote_state"),"outcome_unknown");yes(Files.exists(Path.of(r.getString("path"))));}});
  check("Print retirement is scoped and does not relabel a finished request",f->{try(PrintQueue p=new PrintQueue(new Context(f.dir.toString()))){String id=UUID.randomUUID().toString();p.add(S,new JSONObject().put("id",id),staged(f),"cloud");fail(()->RecoveryLedger.retirePrint(p,"wrong",id));p.update(id,"done","operator_confirmed","",0,false);fail(()->RecoveryLedger.retirePrint(p,S,id));eq(p.history(S,0).getJSONObject(0).getString("state"),"done");}});
  check("Previous print history paginates beyond a global newest-100 boundary",f->{try(PrintQueue p=new PrintQueue(new Context(f.dir.toString()))){for(int n=0;n<115;n++)p.add(S,new JSONObject().put("id",UUID.randomUUID().toString()),"retained-path","cloud");eq(p.history(S,0).length(),50);eq(p.history(S,50).length(),50);eq(p.history(S,100).length(),15);eq(RecoveryLedger.scopes(f.q,p).length(),1);}});
  check("Print schema1 upgrades additively and keeps remote job state",f->{PrintQueue p=new PrintQueue(new Context(f.dir.toString()));String id=UUID.randomUUID().toString();p.add(S,new JSONObject().put("id",id),staged(f),"local");p.update(id,"accepted","submitting","",0,false);p.getWritableDatabase().execSQL("ALTER TABLE jobs DROP COLUMN archive_job_id");p.getWritableDatabase().execSQL("DROP TABLE recovery_audit");p.getWritableDatabase().execSQL("PRAGMA user_version=1");p.close();try(PrintQueue after=new PrintQueue(new Context(f.dir.toString()))){eq(after.history(S,0).getJSONObject(0).getString("remote_state"),"submitting");RecoveryLedger.retirePrint(after,S,id);eq(after.history(S,0).getJSONObject(0).getString("state"),"retired_local");}});
  check("Audit exports decisions but not paths, photos or credentials",f->{f.baseline(0);String j=f.incoming("content://SECRET-PHOTO",false);RecoveryLedger.retireUpload(f.q,S,j);try(PrintQueue p=new PrintQueue(new Context(f.dir.toString()))){JSONObject r=RecoveryLedger.auditReport(f.q,p).getJSONArray("uploads").getJSONObject(0);eq(r.getString("action"),"stop_local_retry");eq(r.getString("job_id"),j);yes(!r.has("uri"));yes(!r.has("path"));yes(!r.has("token"));}});
  check("Exact H5.3 schema4 source upgrades to schema6, preserves records, and allows reviewed revision",f->{
   Path dir=Files.createTempDirectory("lensdrop-h53-migration-");Context context=new Context(dir.toString());String id;
   try{try(FrozenH53QueueDb old=new FrozenH53QueueDb(context)){old.add(S,"content://old","OLD.JPG",120,20);try(Cursor c=old.getReadableDatabase().rawQuery("SELECT id FROM jobs",null)){c.moveToFirst();id=c.getString(0);}old.state(id,"blocked","source_changed",2,0);}
    try(QueueDb current=new QueueDb(context)){eq(current.jobState(S,id),"blocked");RecoveryLedger.retireUpload(current,S,id);String next=UUID.randomUUID().toString();RecoveryLedger.replacement(current,S,id,"NEW.JPG",120,20,"b".repeat(64),staged(f),next);eq(current.jobState(S,next),"candidate");try(Cursor c=current.getReadableDatabase().rawQuery("PRAGMA user_version",null)){c.moveToFirst();eq(c.getInt(0),6);}}
   }finally{try(var stream=Files.walk(dir)){for(Path x:stream.sorted(Comparator.reverseOrder()).toList())Files.delete(x);}}
  });
  System.out.println("PASSED "+count+" recovery/identity/ledger cases");
 }
}
